Update: Calling `fetch` followed by `try_next` as a replacement of `fetch_optional` works properly:

```rust
    for i in 0..10 {
        println!("Query #{i} with results.");
        let r = sqlx::query("SELECT 1 + 1")
            .fetch(&pool)
            .try_next()
            .await
            .unwrap()
            .is_some();
        println!("Result: {r}");
    }

    for i in 0..10 {
        println!("Query #{i} without results.");
        let r = sqlx::query("SELECT 1 + 1 WHERE 1=0")
            .fetch(&pool)
            .try_next()
            .await
            .unwrap()
            .is_some();
        println!("Result: {r}");
    }
```
